-- NusaMora: daftarkan tema undangan 2D universal (engine /undangan) sebagai template paket Essential.
-- Jalankan SETELAH essential-schema.sql, dan jalankan ulang setiap kali menambah tema baru di assets/invite/themes.
-- Slug template = id folder tema. capabilities.engine = 'universal-2d' membuat editor & preview memakai engine ini.
-- Harga, urutan, dan status bisa diubah dari Admin > Manajemen Template.

with t(slug, name, cats, description, sort) as (values
  ('marun-songket', 'Marun Songket',         '{wedding,engagement}'::text[],                    'Marun dan emas dengan pola anyaman songket, sulur bunga, dan pintu cover yang terbelah.', 30),
  ('sage-garden',   'Sage Garden',           '{wedding,engagement,birthday,aqiqah}'::text[],    'Hijau sage yang tenang dengan daun berguguran, garis tipis, dan cover yang memudar lembut.', 31),
  ('biru-malam',    'Biru Malam',            '{wedding,engagement,graduation,corporate}'::text[], 'Navy dan emas seperti langit malam, dengan titik cahaya yang jatuh pelan.', 32),
  ('blush-rose',    'Blush Rose',            '{wedding,engagement,birthday}'::text[],           'Merah muda lembut dengan pola kawung, hati dan kelopak mawar yang melayang.', 33),
  ('batak-ulos',    'Batak Ulos',            '{wedding,engagement}'::text[],                    'Adat Batak: rumah bolon, ulos, gorga, lentera, dan ilustrasi pengantin berbusana adat.', 34),
  ('korean-royal',  'Korean Royal Wedding',  '{wedding,engagement}'::text[],                    'Istana hanok di bawah bunga sakura: lentera kertas, gerbang bunga, jembatan merah, kantong bokjumeoni, dan sentuhan aksara Hangul.', 35),
  ('javanese-wedding', 'Javanese Wedding',   '{wedding,engagement}'::text[],                    'Pawiwahan adat Jawa: pendopo joglo berukir emas, gunungan, pelaminan, lentera, payung songsong, batik kawung, dan sentuhan aksara Jawa.', 36),
  ('chinese-wedding', 'Chinese Wedding',     '{wedding,engagement}'::text[],                    'Pernikahan Tionghoa: aula merah berukir naga, lampion merah, gerbang bulan 囍, bunga plum dan peony, kipas, serta pelaminan merah-emas.', 37),
  ('istana-pink',   'Istana Pink',           '{birthday}'::text[],                              'Pesta ulang tahun di istana merah muda: gerbang kastil, balon hati, air mancur, kereta permen, kado berpita, dan bendera segitiga.', 40),
  ('dino-adventure', 'Dino Adventure',       '{birthday}'::text[],                              'Pesta ulang tahun petualangan di lembah dinosaurus: gunung berapi, obor, telur dino, fosil, gua, balon jejak kaki, dan para dino lucu.', 41),
  ('metal-rock',    'Metal Rock Party',      '{birthday}'::text[],                              'Pesta ulang tahun bergaya konser metal rock: panggung neon merah, gitar listrik, drum, ampli, tengkorak bersayap, mahkota krom, dan percikan petir.', 42),
  ('kpop-party',    'K-Pop Party',           '{birthday}'::text[],                              'Pesta ulang tahun ala konser K-Pop: panggung neon ungu di bawah sakura, lightstick, bola disko, photo booth, dan karakter chibi idola berbusana ungu.', 43),
  ('kuromi-party',  'Kuromi Party',          '{birthday}'::text[],                              'Pesta ulang tahun ungu-pink bergaya Kuromi: panggung tirai ungu di taman kastil, air mancur, balon hati, photo booth, mesin capit, dan untaian lampu bintang.', 44),
  ('aqiqah-istana-pink', 'Aqiqah Istana Pink', '{aqiqah}'::text[],                              'Tasyakuran aqiqah bernuansa istana merah muda: lentera emas, Al-Qur''an di atas rehal, bulan sabit, gazebo bertirai, teddy dan kelinci, serta ilustrasi bayi berhijab bermahkota.', 50),
  ('viking-party',  'Viking Party',          '{birthday}'::text[],                              'Pesta ulang tahun petualangan Viking: panggung kayu bertanduk dengan kapal naga dan air terjun, kapal layar bergaris, kedai makanan, tenda berbulu, perisai, kapak, dan lentera hangat.', 45),
  ('samurai-sakura', 'Samurai Sakura Party', '{birthday}'::text[],                           'Pesta ulang tahun festival Jepang: panggung kayu di bawah sakura dengan gerbang torii, kabuto emas, katana, lentera kertas, kedai jajanan, daruma, kipas, dan karakter chibi berpakaian samurai serta hakama.', 46),
  ('little-circus', 'Little Circus', '{birthday}'::text[],                                  'Pesta ulang tahun sirkus mungil: panggung tenda belang merah-putih dengan tirai dan lampu bohlam, komidi putar, gerobak popcorn, loket tiket, photo booth, serta karakter chibi badut, pesulap, dan pemain drum.', 47),
  ('little-prince', 'Little Prince', '{birthday}'::text[],                                  'Pesta ulang tahun pangeran kecil: panggung istana putih di bawah langit malam berbintang dengan bulan purnama, mahkota emas, balon udara, teleskop, rak buku, air mancur, dan karakter chibi pangeran serta putri berjubah biru-emas.', 48),
  ('little-chef', 'Little Chef', '{birthday}'::text[],                                  'Pesta ulang tahun koki cilik: panggung dapur ceria dengan gapura topi koki dan tirai merah-putih, kedai roti, oven pizza, papan menu, meja kotak-kotak, serta karakter chibi koki dan pastry chef berseragam merah.', 49),
  ('little-doctor', 'Little Doctor', '{birthday}'::text[],                                  'Pesta ulang tahun dokter cilik: panggung klinik biru muda dengan sofa emas, kue detak jantung, balon palang merah, serta karakter chibi dokter dan perawat berjas putih.', 50),
  ('little-princess', 'Little Princess', '{birthday}'::text[],                                  'Pesta ulang tahun putri kecil bergaya dongeng sepatu kaca: aula istana putih-biru dengan lampu kristal, karpet biru, bunga hydrangea, lentera emas, serta karakter chibi pangeran dan putri bergaun biru muda.', 51),
  ('little-swan', 'Little Swan Princess', '{birthday}'::text[],                                  'Pesta ulang tahun putri angsa: aula istana merah muda-lavender dengan angsa bermahkota, danau berkilau, lampu kristal, bunga mawar, serta karakter chibi pangeran dan putri bergaun sayap angsa.', 52),
  ('little-barbie', 'Little Princess Pink Luxe', '{birthday}'::text[],                                  'Pesta ulang tahun putri pink mewah: panggung istana merah muda dengan menara puri, lampu kristal, vas emas berisi mawar, karpet glamor, serta karakter chibi pangeran dan putri bergaun pink berkilau.', 53),
  ('little-arab', 'Little Princess Arabian Night', '{birthday}'::text[],                                  'Pesta ulang tahun putri malam Arabia: panggung emas berukir dengan lentera, tirai ungu, bulan sabit dan masjid di tepi danau, serta karakter chibi pangeran dan putri berbusana ungu-emas.', 54),
  ('little-ice', 'Little Ice Princess', '{birthday}'::text[],                                  'Pesta ulang tahun putri es: aula salju berhias aurora, istana es, kristal biru, kereta camilan dan gapura bersalju, serta karakter chibi pangeran & putri berbusana biru-perak.', 55),
  ('little-forest', 'Little Magic Forest', '{birthday}'::text[],                                  'Pesta ulang tahun hutan ajaib: panggung kayu di bawah pohon rindang berhias lentera, jamur, air terjun dan rumah pohon, serta karakter chibi peri, pemanah, dan anak rubah berbusana hijau-krem.', 56),
  ('little-candy', 'Little Candyland', '{birthday}'::text[],                                  'Pesta ulang tahun negeri permen: panggung merah muda dengan gapura permen, lolipop raksasa, bukit gula-gula, pelangi dan istana kue, serta karakter chibi bergaun krim-sprinkle.', 57),
  ('little-strawberry', 'Little Strawberry Garden', '{birthday}'::text[],                                  'Pesta ulang tahun kebun strawberry ceria: panggung merah muda berpagar putih, taplak gingham, rumah strawberry, bunga dan keranjang buah, serta karakter chibi bergaun gingham-renda.', 58),
  ('little-pearl', 'Little Ocean Pearl', '{birthday}'::text[],                                  'Pesta ulang tahun mutiara lautan: panggung marmer dengan gapura kerang dan lumba-lumba, karang warna-warni, istana bawah laut, serta karakter chibi pangeran, putri duyung, pelaut, dan peri berbusana biru-ungu mutiara.', 59),
  ('little-racing', 'Little Racing Champion', '{birthday}'::text[],                                  'Pesta ulang tahun racing champion: panggung podium berlampu dengan gapura bendera finish, sirkuit balap, tenda pit stop, trofi emas, serta karakter chibi pembalap, mekanik, dan kru berseragam merah-hitam kotak-kotak.', 60),
  ('little-police', 'Little Police Patrol', '{birthday}'::text[],                                  'Pesta ulang tahun polisi patroli: panggung podium berlampu biru-emas dengan markas polisi dan helikopter, mobil patroli, menara jaga, serta karakter chibi polisi, polisi lalu lintas, dan pilot berseragam biru tua kotak-kotak.', 61),
  ('little-construction', 'Little Construction Zone', '{birthday}'::text[],                                  'Pesta ulang tahun zona konstruksi: panggung podium berlampu kuning-hitam dengan derek, ekskavator, dan truk, tenda proyek, rambu alat berat, serta karakter chibi pekerja bangunan berhelm dan rompi safety.', 62),
  ('little-firefighter', 'Little Firefighter', '{birthday}'::text[],                                  'Pesta ulang tahun little firefighter: panggung podium berlampu dengan pos pemadam, truk damkar dan helikopter, hidran, serta karakter chibi pemadam kebakaran berhelm dan seragam merah-kuning.', 63),
  ('little-pilot', 'Little Pilot', '{birthday}'::text[],                                  'Pesta ulang tahun little pilot: panggung podium berlampu biru-emas dengan landasan bandara, pesawat, dan menara kontrol, awan-awan lembut, serta karakter chibi pilot, pramugari, dan kru bandara berseragam biru tua.', 64),
  ('little-train', 'Little Train Adventure', '{birthday}'::text[],                                  'Pesta ulang tahun petualangan kereta api: panggung kayu berlampu dengan lokomotif uap, jembatan lengkung, dan stasiun bergaya klasik, serta karakter chibi masinis, kondektur, dan penumpang berseragam biru tua-merah marun.', 65),
  ('little-rocket', 'Little Rocket Explorer', '{birthday}'::text[],                                  'Pesta ulang tahun penjelajah roket: panggung podium berlampu dengan peluncuran roket, bulan, dan observatorium di langit berbintang, serta karakter chibi astronot, penjelajah, dan kru antariksa berseragam biru tua-oranye.', 66),
  ('little-dino', 'Little Dino Friends', '{birthday}'::text[],                                  'Pesta ulang tahun dino friends: panggung podium berlampu dengan gerbang batu berselimut sulur, hutan prasejarah, air terjun, dan gunung berapi, serta karakter chibi penjelajah berkostum dino.', 67),
  ('little-farm', 'Little Farm Friends', '{birthday}'::text[],                                  'Pesta ulang tahun peternakan: panggung lumbung merah berlampu dengan bendera kotak-kotak, jerami, kincir angin, dan padang rumput, serta karakter chibi petani cilik berkostum overall, topi jerami, dan sapi.', 68),
  ('little-baseball', 'Baseball League', '{birthday}'::text[],                                  'Pesta ulang tahun baseball league: panggung podium berlampu dengan lencana bola dan tongkat, lapangan, papan skor, dan tribun penonton, serta karakter chibi pemain, pemandu sorak, dan penonton berseragam biru-merah.', 69),
  ('little-basketball', 'Basketball All-Star', '{birthday}'::text[],                                  'Pesta ulang tahun basketball all-star: panggung podium berlampu dengan lencana bola basket, ring, banner bintang, dan tribun penonton, serta karakter chibi pemain, pemandu sorak, dan penonton berseragam biru-oranye.', 70),
  ('little-soccer', 'Soccer Champions', '{birthday}'::text[],                                  'Pesta ulang tahun sepak bola: panggung podium berlampu dengan lencana bola dan pita emas, gawang, banner juara, serta lapangan hijau, bersama karakter chibi pemain, pemandu sorak, kiper, dan penonton berseragam biru-emas.', 71),
  ('little-pirates', 'Little Pirates', '{birthday}'::text[],                                  'Pesta ulang tahun bajak laut kecil: panggung kapal kayu berlampu dengan topi bajak laut, kompas, peta harta, kapal layar di lautan, serta karakter chibi kapten, bajak laut, dan pangeran berkostum merah-cokelat.', 72),
  ('arabian-knight', 'Arabian Knight Wedding', '{wedding,engagement}'::text[],                    'Pernikahan malam Arabia: panggung emas berukir dengan lentera, tirai ungu, bulan sabit dan masjid di tepi danau, serta pengantin chibi berbusana ungu-emas.', 73),
  ('little-wizard', 'Wizard Academy', '{birthday}'::text[],                                  'Pesta ulang tahun akademi penyihir: panggung kastil berlampu dengan topi sihir, panji asrama, jendela bintang, dan kuali ramuan, serta karakter chibi penyihir cilik berjubah ungu-emas.', 74),
  ('little-sakura', 'Sakura Wedding', '{wedding,engagement}'::text[],                    'Pernikahan taman sakura: panggung bunga ceri dengan lentera emas, jembatan merah di tepi danau, serta pengantin chibi berbusana tradisional Jepang.', 75),
  ('little-hackathon', 'Hackathon Night', '{corporate,seminar}'::text[],                    'Event hackathon bernuansa neon: kota malam ungu dengan gerbang cahaya, panggung bercincin neon, kursi gaming dan booth-booth acara, serta peserta chibi berkode </>.', 76),
  ('little-idol', 'Idol Birthday Event', '{birthday}'::text[],                    'Fan party ulang tahun idol K-pop: panggung konser neon ungu-pink dengan lampu sorot, spanduk mahkota, dan booth fan, serta fans chibi berlightstick.', 77),
  ('little-bugis', 'Bugis Makassar Wedding', '{wedding,engagement}'::text[],                    'Pernikahan adat Bugis Makassar: rumah panggung kayu berukir emas dengan tirai merah, payung dan lentera emas, kapal pinisi di tepi laut, serta pengantin chibi berbusana bodo dan baju bella dada.', 78)
)
insert into public.templates (slug, name, description, thumbnail_url, preview_url, package_type, categories, theme_key, status, sort, capabilities)
select t.slug, t.name, t.description, '/assets/invite/themes/' || t.slug || '/thumb.webp', '/preview?demo=' || t.slug,
       'essential', t.cats, t.slug, 'published', t.sort, '{"engine":"universal-2d"}'::jsonb
from t
on conflict (slug) do update set
  thumbnail_url = excluded.thumbnail_url, preview_url = excluded.preview_url, package_type = excluded.package_type,
  theme_key = excluded.theme_key, capabilities = public.templates.capabilities || excluded.capabilities;

-- Versi awal engine terdaftar sebagai "nusa-essential"; kini setara tema marun-songket (alias di themes/index.json).
update public.templates set status = 'archived' where slug = 'nusa-essential' and status = 'published';
